package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TokenBuffer.deserialize
 */
public class TokenBuffer_deserialize_TriageGen1Test {

    private ObjectMapper mapper;
    private DeserializationContext ctxt;
    private JsonParser jp;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        ctxt = mock(DeserializationContext.class);
        jp = mock(JsonParser.class);
        tokenBuffer = new TokenBuffer(mapper);
    }

    /**
     * Tests that deserialize returns the same instance (this) and 
     * calls copyCurrentStructure.
     */
    @Test
    public void testDeserializeReturnsSelfAndCallsCopy() throws IOException {
        // We need to spy on the tokenBuffer to verify that copyCurrentStructure is called
        TokenBuffer spyBuffer = spy(tokenBuffer);

        // Execute the method under test
        TokenBuffer result = spyBuffer.deserialize(jp, ctxt);

        // Verify the method returns 'this'
        assertSame("The method should return the same TokenBuffer instance", spyBuffer, result);

        // Verify that copyCurrentStructure was called with the provided parser
        verify(spyBuffer, times(1)).copyCurrentStructure(jp);
    }

    /**
     * Tests the behavior when copyCurrentStructure throws an IOException.
     * Although the implementation of deserialize calls copyCurrentStructure, 
     * we must ensure the exception propagates as declared in the signature.
     */
    @Test(expected = IOException.class)
    public void testDeserializePropagatesIOException() throws IOException {
        TokenBuffer spyBuffer = spy(tokenBuffer);

        // Simulate an IOException being thrown by copyCurrentStructure
        doThrow(new IOException("Simulated IO Error")).when(spyBuffer).copyCurrentStructure(jp);

        // This should throw the IOException
        spyBuffer.deserialize(jp, ctxt);
    }

    /**
     * Tests the scenario mentioned in the code comments regarding the special case 
     * of starting from FIELD_NAME. 
     * Since 'deserialize' simply calls 'copyCurrentStructure', the logic of handling 
     * the token state is actually encapsulated within copyCurrentStructure. 
     * This test ensures the 'deserialize' wrapper behaves correctly in a standard flow.
     */
    @Test
    public void testDeserializeWithFieldToken() throws IOException {
        TokenBuffer spyBuffer = spy(tokenBuffer);

        // Mock the parser to return a FIELD_NAME token
        when(jp.currentToken()).thenReturn(JsonToken.FIELD_NAME);

        // Execute
        TokenBuffer result = spyBuffer.deserialize(jp, ctxt);

        // Verify
        assertSame(spyBuffer, result);
        verify(spyBuffer).copyCurrentStructure(jp);
    }
}
